import { NetworkThrottle, Button, Progress } from "march/ui"

// yükleme yarışı: ağı seç, fotoğrafı indir; çubuk gelen baytları sayar (gövde akış olarak okunur), süre yazılır
export function LoadingRace() {
  let $got = 0
  let $total = 1
  let $note = "Bir ağ seç, sonra indir"
  const load = async () => {
    const t0 = performance.now()
    $got = 0; $note = "bağlanıyor…"
    try {
      const r = await fetch(`/media/dusk.jpg?t=${Date.now()}`)
      $total = Number(r.headers.get("content-length")) || 21531
      const reader = r.body!.getReader()
      for (;;) { const { done, value } = await reader.read(); if (done) break; $got += value.byteLength; $note = `${Math.round($got / 1000)} kB` }
      $note = `${Math.round(performance.now() - t0)} ms`
    } catch { $note = "ağ yok: indirilemedi" }
  }
  return <div sx={{ flex: "col", gap: 3 }}>
    <NetworkThrottle custom={false} requests={false} />
    <div sx={{ flex: ["row", "center"], gap: 2 }}>
      <Button size="sm" variant="primary" on:click={() => void load()}>Fotoğrafı indir</Button>
      <span sx={{ text: "sm", color: "muted" }}>{() => $note}</span>
    </div>
    <Progress value={() => Math.min(100, ($got / $total) * 100)} label="İndirilen" />
  </div>
}

import { NetworkThrottle, Button, Alert, Spinner } from "march/ui"

// gerçek hayattan: akış her açılışta veriyi yükler; yavaş ağda yükleniyor görünür, çevrimdışıyken son kopya gösterilir
// ve "yeniden dene" sunulur. Paneldeki şelalede her isteğin bekleme ve indirme süresi görünür.
let cache: string[] = ["(önbellek) Dünkü buluşma fotoğrafları", "(önbellek) Elif seni etiketledi"]

export function OfflineFeed() {
  let $items: string[] = []
  let $state: "idle" | "loading" | "ok" | "offline" = "idle"
  const load = async () => {
    $state = "loading"
    try {
      const r = await fetch(`/export-sizes.json?t=${Date.now()}`)
      const data = await r.json() as Record<string, unknown>
      $items = Object.keys(data).slice(0, 4).map((k) => `Yeni: ${k}`)
      cache = $items
      $state = "ok"
    } catch {
      $items = cache
      $state = "offline"
    }
  }
  void load()
  return <div sx={{ flex: ["row", "wrap"], gap: 4 }}>
    <NetworkThrottle max={5} />
    <div class="m-card" sx={{ flex: "col", gap: 2, p: 4 }}>
      <span sx={{ text: ["lg", "bold"] }}>Akış</span>
      {() => ($state === "loading" ? <Spinner label="Yükleniyor" /> : null)}
      {() => ($state === "offline" ? <Alert tone="warn" title="Çevrimdışısın">Son kaydedilen akış gösteriliyor.</Alert> : null)}
      {() => $items.map((t) => <span sx={{ text: "sm" }}>{t}</span>)}
      <Button size="sm" on:click={() => void load()}>Yeniden dene</Button>
    </div>
  </div>
}

import { signal } from "march"
import { NetworkThrottle } from "march/ui"

// NetworkThrottle'ın bütün özellikleri: scope (yalnız bu kodun çağrıları), value (sinyal) ve onChange, presets (kendi
// ağların), gauge, custom, requests, max, label, class
// bir ağ: bant genişlikleri kb/s (null: limit yok), gecikme ms ya da çevrimdışı
type Net = { offline?: boolean; down?: number | null; up?: number | null; latency?: number }
const PRESETS: { id: string; label: string; profile: Net }[] = [
  { id: "none", label: "Kısıtsız", profile: {} },
  { id: "cafe", label: "Kafe Wi-Fi", profile: { down: 2500, up: 500, latency: 120 } },
  { id: "metro", label: "Metroda", profile: { down: 250, up: 100, latency: 900 } },
  { id: "offline", label: "Çevrimdışı", profile: { offline: true } },
]

export function NetworkThrottleLab() {
  const net = signal({} as Net)
  let $last = "değişiklik yok"
  return <div sx={{ flex: "col", gap: 3 }}>
    <NetworkThrottle class="lab-net" scope={(stack: string) => stack.includes("blob:")} value={net} onChange={(p: Net) => ($last = JSON.stringify(p))}
      presets={PRESETS} gauge custom requests max={6} label="Önizlemenin ağı" />
    <span class="lab-last" sx={{ text: "sm", color: "muted" }}>{() => `Son ağ: ${$last}`}</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { NetworkThrottleLab } from "./NetworkThrottleLab.tsx"

// NetworkThrottleLab'in testleri: kaydedince Testler sekmesinde çalışır
test("kendi ağları listelenir; panel adını label'dan alır", () => {
  const s = renderTest(() => <NetworkThrottleLab />)
  expect(s.sees("Kafe Wi-Fi")).toBe(true)
  expect(s.sees("Metroda")).toBe(true)
  expect(s.get(".lab-net")?.getAttribute("aria-label")).toBe("Önizlemenin ağı")
})

test("bir ağ seçilince onChange onu bildirir", async () => {
  const s = renderTest(() => <NetworkThrottleLab />)
  await s.click("Metroda")
  expect(s.get(".lab-last")?.textContent).toContain("\"latency\":900")
  await s.click("Kısıtsız")
  expect(s.get(".lab-last")?.textContent).toContain("{}")
})

test("hız göstergesi ve istek şelalesi görünür", () => {
  const s = renderTest(() => <NetworkThrottleLab />)
  expect(s.get(".lab-net .m-nt-gauge")).toBeTruthy()
  expect(s.get(".lab-net .m-nt-log")).toBeTruthy()
})
